package io.ecosync.chat;
import java.util.*;
import java.math.*;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Component;
/** Query-local deterministic operations; no source transport and no model-supplied numbers. */
@Component
public class ChatKnowledge {
 private final List<Map<String,Object>> mappings;private final ChatBindings bindings;
 public ChatKnowledge(){this(null);}
 @org.springframework.beans.factory.annotation.Autowired @SuppressWarnings("unchecked") public ChatKnowledge(ChatBindings bindings){this.bindings=bindings;try{var doc=ChatData.object(new ClassPathResource("chat/relationships-v1.json").getContentAsString(java.nio.charset.StandardCharsets.UTF_8),262144);if(!"1.0.0".equals(doc.get("mappingVersion")))throw new IllegalArgumentException();mappings=(List<Map<String,Object>>)doc.get("records");}catch(Exception e){throw new IllegalStateException("Seeded mappings unavailable");}}
 private static final UUID INTERNAL=new UUID(0,0);
 public List<ChatCapabilities.Capability> tools(List<ChatCapabilities.Capability> catalog){var props=new LinkedHashMap<String,Object>();props.put("sourceSystem",Map.of("type","string"));props.put("sourceIdentifier",Map.of("type","string"));props.put("targetSystem",Map.of("type","string"));var mapping=new ChatCapabilities.Capability("approved_mapping","DETERMINISTIC",INTERNAL,INTERNAL,1,"mapping-1.0.0","Approved seeded mappings","Resolve only a unique approved relationship; requires verified canonical source bindings",schema(props,List.of("sourceSystem","sourceIdentifier","targetSystem")),"mapping-1.0.0");var ref=Map.of("type","object","additionalProperties",false,"properties",Map.of("evidence",Map.of("type","string"),"pointer",Map.of("type","string")),"required",List.of("evidence","pointer"));var calc=new ChatCapabilities.Capability("decimal_calculation","DETERMINISTIC",INTERNAL,INTERNAL,1,"decimal-1","Exact decimal calculation","Use numeric values from evidence only; currency/unit must match",schema(Map.of("operation",Map.of("type","string","enum",List.of("SUM","DIFFERENCE")),"operands",Map.of("type","array","items",ref,"minItems",2,"maxItems",8),"currency",Map.of("type","string"),"unit",Map.of("type","string")),List.of("operation","operands","currency","unit")),"calculation");return List.of(mapping,calc);}
 private static Map<String,Object> schema(Map<String,Object> props,List<String> required){return Map.of("type","object","additionalProperties",false,"properties",props,"required",required);}
 public Map<String,Object> mapping(Map<String,Object> args,List<ChatCapabilities.Capability> catalog){ChatData.keys(args,Set.of("sourceSystem","sourceIdentifier","targetSystem"));String source=Objects.toString(args.get("sourceSystem"),""),target=Objects.toString(args.get("targetSystem"),""),id=Objects.toString(args.get("sourceIdentifier"),"");if(id.length()>100||source.equals(target)||catalog.stream().noneMatch(c->c.canonicalSource().equals(source))||catalog.stream().noneMatch(c->c.canonicalSource().equals(target)))throw new ChatFailure("CHAT_MAPPING_UNAVAILABLE");var matching=mappings.stream().filter(m->source.equals(m.get("sourceSystem"))&&target.equals(m.get("targetSystem"))&&id.equals(m.get("sourceIdentifier"))).toList();if(matching.size()!=1||!"APPROVED".equals(matching.getFirst().get("approvalStatus"))||matching.getFirst().get("targetIdentifier")==null)return Map.of("status","AMBIGUOUS_OR_MISSING","mappingVersion","1.0.0","sourceIdentifier",id);var m=matching.getFirst();return Map.of("status","APPROVED","mappingId",m.get("mappingId"),"mappingVersion","1.0.0","sourceSystem",source,"sourceIdentifier",id,"targetSystem",target,"targetIdentifier",m.get("targetIdentifier"));}
 @SuppressWarnings("unchecked") public Map<String,Object> calculate(UUID org,Map<String,Object> args,List<ChatEvidence> evidence){ChatData.keys(args,Set.of("operation","operands","currency","unit"));String op=Objects.toString(args.get("operation"),""),currency=Objects.toString(args.get("currency"),""),unit=Objects.toString(args.get("unit"),"");if(!Set.of("SUM","DIFFERENCE").contains(op)||!currency.matches("[A-Z]{3}|NONE")||!unit.matches("[A-Za-z0-9_/-]{1,24}")||!(args.get("operands") instanceof List<?> refs)||refs.size()<2||refs.size()>8)throw new ChatFailure("CHAT_INVALID_CALCULATION");var values=new ArrayList<BigDecimal>();var inputs=new ArrayList<Map<String,Object>>();for(Object raw:refs){if(!(raw instanceof Map<?,?>))throw new ChatFailure("CHAT_INVALID_REFERENCE");var ref=(Map<String,Object>)raw;ChatData.keys(ref,Set.of("evidence","pointer"));var e=evidence.stream().filter(x->x.status().equals("SUCCESS")&&x.id().equals(ref.get("evidence"))).findFirst().orElseThrow(()->new ChatFailure("CHAT_INVALID_REFERENCE"));Object value=ChatData.pointer(e.data(),(String)ref.get("pointer"));if(!(value instanceof String||value instanceof Number)||!value.toString().matches("-?(0|[1-9][0-9]{0,17})(\\.[0-9]{1,8})?"))throw new ChatFailure("CHAT_INVALID_CALCULATION");
   // Unit/currency are grounded in the numeric value's containing object, not trusted model labels.
   String pointer=(String)ref.get("pointer");int slash=pointer.lastIndexOf('/');Object parent=ChatData.pointer(e.data(),slash<0?"":pointer.substring(0,slash));if(bindings==null)throw new ChatFailure("CHAT_MEASURE_UNVERIFIED");var dimensions=bindings.measure(org,e.capability(),pointer,e.data());if(!dimensions.get("currency").equals(currency)||!dimensions.get("unit").equals(unit))throw new ChatFailure("CHAT_INCOMPATIBLE_MEASURES");values.add(new BigDecimal(value.toString()));inputs.add(Map.of("evidence",e.id(),"pointer",pointer));}
  BigDecimal result=values.getFirst();for(int i=1;i<values.size();i++)result=switch(op){case "SUM"->result.add(values.get(i));default->result.subtract(values.get(i));};if(result.precision()>38||result.scale()>18)throw new ChatFailure("CHAT_INVALID_CALCULATION");return Map.of("operation",op,"value",result.toPlainString(),"currency",currency,"unit",unit,"inputs",inputs,"deterministic",true);}
 /** A join must cite exact scalar identifiers actually retrieved from both sources. */
 public boolean related(UUID org,List<ChatEvidence> evidence){if(bindings==null)return false;var mapping=evidence.stream().filter(e->e.capability().name().equals("approved_mapping")&&e.data() instanceof Map<?,?> m&&"APPROVED".equals(m.get("status"))).toList();var sources=evidence.stream().filter(e->!e.capability().kind().equals("DETERMINISTIC")&&e.status().equals("SUCCESS")).map(e->e.capability().canonicalSource()).collect(java.util.stream.Collectors.toCollection(HashSet::new));if(sources.size()<2)return true;var graph=new HashMap<String,Set<String>>();for(var e:mapping){var m=(Map<?,?>)e.data();String left=m.get("sourceSystem").toString(),right=m.get("targetSystem").toString();boolean a=evidence.stream().anyMatch(v->v.capability().canonicalSource().equals(left)&&bindings.identifiers(org,v.capability(),v.data()).equals(Set.of(m.get("sourceIdentifier").toString()))),b=evidence.stream().anyMatch(v->v.capability().canonicalSource().equals(right)&&bindings.identifiers(org,v.capability(),v.data()).equals(Set.of(m.get("targetIdentifier").toString())));if(a&&b){graph.computeIfAbsent(left,k->new HashSet<>()).add(right);graph.computeIfAbsent(right,k->new HashSet<>()).add(left);}}var reached=new HashSet<String>();var queue=new ArrayDeque<String>();queue.add(sources.iterator().next());while(!queue.isEmpty()){String next=queue.remove();if(reached.add(next))queue.addAll(graph.getOrDefault(next,Set.of()));}return reached.containsAll(sources);}
 private static boolean contains(Object data,Object id){if(data instanceof Map<?,?> m)return m.values().stream().anyMatch(v->contains(v,id));if(data instanceof List<?> l)return l.stream().anyMatch(v->contains(v,id));return data!=null&&data.toString().equals(Objects.toString(id));}
}
